begin;
create extension if not exists pgtap with schema extensions;
grant usage on schema extensions to cuevo_api;
set local search_path=extensions,pg_catalog;
select no_plan();
create temporary table programme_ids(pack uuid,stage uuid,objective uuid,programme uuid,course uuid);
grant select,insert,update on programme_ids to cuevo_api;
insert into app.courses(school_id,id,class_id,subject_id,created_by,title,description,status)values('10000000-0000-4000-8000-000000000001','91000000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000001','43000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000004','Programme golden','Synthetic','PUBLISHED');
set local role cuevo_api;select set_config('app.actor_id','20000000-0000-4000-8000-000000000001',true);select set_config('app.school_id','10000000-0000-4000-8000-000000000001',true);
insert into programme_ids(pack,course)select(internal.configure_curriculum('version.create',null,'{"packId":"synthetic-programme-golden","kind":"school_custom","framework":"School Custom","programme":"Synthetic primary","version":"school-1","scope":"synthetic-primary","sourceStatus":"VERIFIED","rightsStatus":"PERMITTED","sourceLocation":"repo:synthetic","sourceChecksum":null,"synthetic":true,"reason":"Technical golden case"}','programme-pack-golden',repeat('a',64),'programme-golden')->>'id')::uuid,'91000000-0000-4000-8000-000000000001';
update programme_ids set stage=(internal.configure_curriculum('reference.create',null,jsonb_build_object('packVersionId',pack,'parentId',null,'type','stage','title','Synthetic primary','description','School-authored stage','code',null,'sequence',1,'subjectId',null,'yearGroupId',null),'programme-stage-golden',repeat('b',64),'programme-golden')->>'id')::uuid;
update programme_ids set objective=(internal.configure_curriculum('reference.create',null,jsonb_build_object('packVersionId',pack,'parentId',stage,'type','objective','title','Synthetic explanation objective','description','Explain a school-authored example','code',null,'sequence',1,'subjectId','43000000-0000-4000-8000-000000000001','yearGroupId','42000000-0000-4000-8000-000000000001'),'programme-objective-golden',repeat('c',64),'programme-golden')->>'id')::uuid;
select internal.transition_curriculum_lifecycle((select pack from programme_ids),'{"state":"APPROVED","expectedRevision":1,"reviewBasis":"SCHOOL_AUTHORED","artifactDirectory":null,"replacementVersionId":null,"reason":"Reviewed synthetic school source","confirmTransition":true}',null,'programme-lifecycle-0',repeat('a',64),'curriculum-fixture');
select internal.transition_curriculum_lifecycle((select pack from programme_ids),'{"state":"ACTIVE","expectedRevision":2,"reviewBasis":"SCHOOL_AUTHORED","artifactDirectory":null,"replacementVersionId":null,"reason":"Reviewed synthetic school source","confirmTransition":true}',null,'programme-lifecycle-1',repeat('a',64),'curriculum-fixture');
update programme_ids set programme=(internal.configure_curriculum('programme.create',null,jsonb_build_object('packVersionId',pack,'name','Synthetic selected vertical','classId','30000000-0000-4000-8000-000000000001','subjectId','43000000-0000-4000-8000-000000000001','yearGroupId','42000000-0000-4000-8000-000000000001','confirmConfiguration',true),'programme-create-golden',repeat('d',64),'programme-golden')->>'id')::uuid;
select lives_ok($$select internal.configure_curriculum('course.configure',(select course from programme_ids),jsonb_build_object('programmeId',(select programme from programme_ids),'referenceId',(select objective from programme_ids),'expectedVersion',1,'confirmConfiguration',true),'programme-course-golden',repeat('e',64),'programme-golden')$$,'synthetic programme binds native objective to course');
select is((select count(*)from app.programme_course_contexts where course_id=(select course from programme_ids)),1::bigint,'one immutable course programme context');
select lives_ok($$select internal.configure_curriculum('learner.configure',null,jsonb_build_object('programmeId',(select programme from programme_ids),'learnerId','20000000-0000-4000-8000-000000000012','status','active','confirmAccessChange',true),'programme-learner-golden',repeat('f',64),'programme-golden')$$,'enrolled learner receives explicit programme assignment');
reset role;
savepoint programme_scope;
update app.memberships set effective_to='2026-09-30T00:00:00Z'where school_id='10000000-0000-4000-8000-000000000001'and actor_id='20000000-0000-4000-8000-000000000012';
set local role cuevo_api;select set_config('app.actor_id','20000000-0000-4000-8000-000000000001',true);
select throws_ok($$select internal.configure_curriculum('learner.configure',null,jsonb_build_object('programmeId',(select programme from programme_ids),'learnerId','20000000-0000-4000-8000-000000000012','status','active','confirmAccessChange',true),'programme-learner-expired',repeat('f',64),'programme-golden')$$,'42501',null,'expired learner cannot gain programme scope');
reset role;rollback to programme_scope;
set local role cuevo_api;
select throws_ok($$select internal.configure_curriculum('version.create',null,'{"packId":"unverified-official","kind":"curriculum","framework":"Cambridge","programme":"IGCSE","version":"REQUIRES_REVIEW","scope":"unknown","sourceStatus":"VERIFIED","rightsStatus":"PERMITTED","sourceLocation":"repo:unknown","sourceChecksum":null,"synthetic":false,"reason":"Cannot assert authority"}','programme-official-golden',repeat('f',64),'programme-golden')$$,'22023',null,'official authority never inferred from configuration');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000012',true);
select throws_ok($$select internal.configure_curriculum('learner.configure',null,'{}','programme-denied-golden',repeat('f',64),'programme-golden')$$,'42501',null,'student cannot assign programme or permissions');
reset role;
select throws_ok($$update app.curriculum_versions set version='overwrite'where id=(select pack from programme_ids)$$,'55000',null,'used source version immutable');
select ok(not exists(select 1 from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='app'and c.relname in('curriculum_versions','curriculum_references','programme_instances','programme_course_contexts')and c.relkind='r'and(not c.relrowsecurity or not c.relforcerowsecurity)),'programme contexts force RLS');
select*from finish();rollback;
